'use strict';
const C=window.SITE_CONFIG, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-2-1-6-2-10 1zM12 5v15"/>',test:'<rect x="5" y="4" width="15" height="18" rx="2"/><path d="M9 2h7v4H9zM9 10h7M9 14h7M9 18h4"/>',chart:'<path d="M3 3v18h18M7 16l5-6 4 3 5-7"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 9 6-3 6 3-2-9M10 8l1 1 3-3"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',admin:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>'};
const ico=n=>`<span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[n]||icons.book}</svg></span>`;
const art=()=>`<svg viewBox="0 0 300 280" role="img" aria-label="Livros formando uma escada até uma estrela"><circle cx="145" cy="145" r="107" fill="#365c4b"/><circle cx="145" cy="145" r="84" fill="none" stroke="#78937b" stroke-dasharray="3 9"/><path d="M47 218h73v-23h47v-32h48v-35h43" fill="none" stroke="#7c9878" stroke-width="2" stroke-dasharray="5 5"/><g transform="rotate(-9 115 201)"><rect x="40" y="209" width="119" height="25" rx="4" fill="#95b382"/><path d="M50 213h106v16H50" fill="#e9efda"/><rect x="50" y="179" width="123" height="27" rx="4" fill="#c6d9a4"/><path d="M61 185h107v15H61" fill="#f4f6e9"/><rect x="74" y="145" width="125" height="30" rx="4" fill="#e2b993"/><path d="M85 152h108v16H85" fill="#fbefdf"/><rect x="103" y="113" width="124" height="27" rx="4" fill="#c9bed9"/><path d="M114 119h107v15H114" fill="#f3eef7"/></g><path d="m228 43 9 20 22 3-16 15 4 22-19-10-19 10 4-22-16-15 22-3z" fill="#d8ebb9"/><path d="m70 72 4 9 10 2-8 7 2 10-8-5-9 5 2-10-7-7 10-2z" fill="#b5c6a2"/><path d="M260 126v10m-5-5h10M55 130v10m-5-5h10" stroke="#93b08b" stroke-width="2"/></svg>`;
const brand=()=>'<a href="#" class="brand" data-action="home"><img src="icon.svg" alt=""><span>Missão Tiradentes<small>Seu próximo passo</small></span></a>';
let course={topics:[],questions:[],exams:[]},user=null,session=null,demo=false,page='dashboard',subject='Todos',query='',quiz=null,exam=null,results=null,timer=null,adminDemo='pending';
let practiceAvailability={},blockedPractice=new Set();
const emptyState=()=>({history:[],lessons:[],checks:[],rewards:[]});
let state=emptyState();
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function persist(){if(demo)localStorage.setItem('tiradentes-demo-v1',JSON.stringify(state));}
function flash(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(flash.t);flash.t=setTimeout(()=>$('#toast').style.display='none',4200)}
function today(){return new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}
function topic(id){return course.topics.find(t=>t.id===id)}
function evidence(){const m=new Map();for(const h of [...state.history].reverse())for(const a of h.items||[])if(!a.annulled&&!m.has(a.id))m.set(a.id,a);return [...m.values()]}
function metrics(id){let v=evidence().filter(a=>a.topic===id).slice(0,8);return {n:v.length,correct:v.filter(a=>a.correct).length,rate:v.length?Math.round(v.filter(a=>a.correct).length/v.length*100):null,uncertain:v.some(a=>a.confidence==='guess')}}
function status(id){const m=metrics(id);return m.n===0?'Ainda não avaliado':m.n<3?(m.rate<70?'Reforçar · poucos dados':'Bom começo · poucos dados'):m.rate>=80?'Consolidando':m.rate<60?'Prioridade de revisão':'Em desenvolvimento'}
function canPractice(id){if(blockedPractice.has(id))return false;const t=topic(id);if(t?.subject==='Matemática')return true;if(Object.hasOwn(practiceAvailability,id))return practiceAvailability[id]>0;return demo?(course.portugueseVariants||[]).some(q=>q.topic===id&&!state.history.some(h=>h.items?.some(a=>a.id===q.id))):true}
function availablePriorities(){return priorities().filter(t=>canPractice(t.id))}
function priorities(){return [...course.topics].sort((a,b)=>{const x=metrics(a.id),y=metrics(b.id);const p=m=>m.n?m.rate+(m.uncertain?-10:0):50;return p(x)-p(y)})}
function earnedAnswers(){return [...new Map(state.history.flatMap(h=>h.items||[]).filter(a=>a.correct&&!a.annulled).map(a=>[a.id,a])).values()]}
function xp(){const good=new Set(earnedAnswers().map(a=>a.id));const recovery=new Set();for(const h of state.history)for(const a of h.items||[])if(a.correct&&!a.annulled&&state.history.some(old=>old.date<h.date&&(old.items||[]).some(x=>(x.id===a.id||(a.topic&&x.topic===a.topic&&(x.template===a.template||!x.template||!a.template)))&&!x.correct)))recovery.add(a.topic);return good.size*10+state.lessons.length*15+recovery.size*20+new Set(state.history.filter(h=>h.kind==='exam'&&h.items.every(a=>a.selected!==null)).map(h=>h.label)).size*50}
function achievements(){const wins=earnedAnswers();const days=new Set(state.history.map(h=>h.date.slice(0,10)));const recovery=state.history.some(h=>(h.items||[]).some(a=>a.correct&&state.history.some(old=>old.date<h.date&&(old.items||[]).some(x=>(x.id===a.id||(a.topic&&x.topic===a.topic&&(x.template===a.template||!x.template||!a.template)))&&!x.correct))));return [{id:'start',title:'Primeiro passo',desc:'Conclua seu primeiro diagnóstico.',ok:state.history.some(h=>h.kind==='diagnostic'),icon:'compass'},{id:'reader',title:'Mente curiosa',desc:'Estude e pratique três aulas diferentes.',ok:state.lessons.length>=3,icon:'book'},{id:'recovery',title:'Virada de jogo',desc:'Supere uma dificuldade em um novo desafio.',ok:recovery,icon:'spark'},{id:'exam',title:'Missão completa',desc:'Finalize uma prova anterior inteira.',ok:state.history.some(h=>h.kind==='exam'&&h.items.filter(a=>a.selected!==null).length===50),icon:'test'},{id:'steady',title:'Constância',desc:'Pratique em três dias diferentes, no seu ritmo.',ok:days.size>=3,icon:'clock'},{id:'balanced',title:'Dupla conquista',desc:'Acerte cinco questões diferentes de cada disciplina.',ok:['Português','Matemática'].every(s=>wins.filter(a=>(topic(a.topic)?.subject||a.subject)===s).length>=5),icon:'award'}]}
function nav(p){if(quiz||exam){modalConfirm('Pausar esta atividade?','O simulado ficará salvo para você continuar depois.',()=>{saveActive();quiz=null;exam=null;clearInterval(timer);page=p;render()});return}page=p;render();window.scrollTo(0,0)}
function saveActive(){if(demo)localStorage.setItem('tiradentes-active',JSON.stringify({quiz,exam}));else if(session)sessionStorage.setItem('tiradentes-active-'+user.id,JSON.stringify({quiz,exam}));}
function clearActive(){if(demo)localStorage.removeItem('tiradentes-active');else sessionStorage.removeItem('tiradentes-active-'+user.id)}
function activeSaved(){const saved=demo?readStore('tiradentes-active',null):JSON.parse(sessionStorage.getItem('tiradentes-active-'+user.id)||'null');if(saved?.quiz){const done=new Set(state.history.flatMap(h=>h.items||[]).map(a=>a.id));const stale=saved.quiz.ids.some(id=>done.has(id)||id.startsWith('autoral-')&&topic(course.questions.find(q=>q.id===id)?.topic)?.subject==='Matemática');if(stale){clearActive();return null}}return saved}

function shell(html){const admin=user?.role==='admin';$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">SUA PREPARAÇÃO</div><nav class="nav" aria-label="Menu principal">${[['dashboard','home','Meu painel'],['lessons','book','Minha trilha'],['simulators','test','Simulados'],['routine','clock','Meu compromisso'],['progress','chart','Evolução'],['rewards','award','Conquistas'],['guide','compass','Guia de ingresso'],...(admin||demo?[['admin','admin','Administração']]:[])].map(([p,i,t])=>`<button class="${page===p?'active':''} ${p==='admin'?'admin-nav':''}" data-page="${p}" aria-label="${esc(t)}" ${page===p?'aria-current="page"':''}>${ico(i)}<span class="desktop-nav-title">${t}</span><span class="mobile-nav-title">${esc({dashboard:"Painel",lessons:"Trilha",simulators:"Simulados",routine:"Rotina"}[p]||t)}</span></button>`).join('')}<button class="mobile-more" data-action="more">${ico('compass')}Mais</button></nav><div class="sidebar-foot"><div class="side-note">${ico('spark')}<br><strong>Pequenos passos. Grandes planos.</strong><br>Aprender também é descobrir o que precisa de mais uma tentativa.</div><div class="profile"><span class="avatar">${demo?'EX':esc(user?.name?.slice(0,2).toUpperCase()||'AL')}</span><div><b>${demo?'Aluno de exemplo':esc(user?.name||'Estudante')}</b><small>${demo?'Demonstração interativa':'Acesso aprovado'}</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><span class="crumb">Preparação / ${esc({dashboard:'Meu painel',lessons:'Minha trilha',simulators:'Simulados',progress:'Evolução',rewards:'Conquistas',guide:'Guia de ingresso',admin:'Administração',routine:'Meu compromisso'}[page]||'Atividade')}</span><span class="mobile-brand">${ico('spark')}</span><div class="top-actions"><span class="pill">${ico('award')}${xp()} XP</span>${demo?'<span class="pill orange">Modo demonstração</span>':''}<button class="btn outline small" data-action="logout">${demo?'Sair da demo':'Sair'}</button></div></header><main id="main" tabindex="-1">${html}<p class="footer-note">Preparatório independente, sem vínculo institucional com a Brigada Militar. ${demo?'Seus exercícios ficam apenas neste navegador. Cadastros reais dependem da ativação do Supabase.':'Seu progresso é salvo na sua conta.'} Conteúdos de apoio não garantem aprovação.</p></main></div></div>`}
function heading(title,sub){return `<div class="heading"><div><div class="eyebrow">Um passo de cada vez</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'})}</span></div>`}
function mission(t,label){return `<div class="mission"><div class="tile-icon ${t.subject==='Português'?'purple':''}">${ico(t.subject==='Português'?'book':'chart')}</div><div class="body"><span class="pill ${t.subject==='Português'?'purple':''}">${esc(label||t.subject)}</span><h3>${esc(t.title)}</h3><p>${t.minutes} min · ${esc(status(t.id))}${!canPractice(t.id)?' · Revisão de conteúdo':''}</p></div><button class="arrow" data-lesson="${t.id}" aria-label="${canPractice(t.id)?'Estudar':'Revisar conteúdo de'} ${esc(t.title)}">${ico('arrow')}</button></div>`}
function landing(){clearInterval(timer);$('#app').innerHTML=`<div class="landing"><nav>${brand()}<div class="nav-btns"><button class="btn outline small" data-auth="login">Entrar</button> <button class="btn small" data-auth="signup">Criar cadastro ${ico('arrow')}</button></div></nav><main id="main" style="padding:0"><section class="landing-hero"><div><div class="eyebrow">Preparatório · Colégio Tiradentes · RS</div><h1>Seu sonho tem<br>um <em>próximo passo.</em></h1><p>Descubra o que você já sabe. Fortaleça o que precisa. Prepare-se para o Tiradentes com aulas curtas, simulados e uma trilha feita a partir do seu desempenho.</p><div class="actions"><button class="btn" data-auth="signup">Quero começar ${ico('arrow')}</button>${C.demo?'<button class="btn outline" data-action="demo">Explorar demonstração</button>':''}</div><p style="">Cadastro → confirmação de e-mail → compromisso de estudo → aprovação → sua preparação.</p></div><div class="landing-art">${art()}<div class="floating-note"><span class="pill">${ico('award')} Uma conquista por vez</span><p style="margin:10px 0 0">Cada dúvida vencida é um passo no seu caminho.</p></div></div></section><div class="landing-band"><div><strong>6 provas anteriores</strong><p>300 questões de 2020/21 a 2025/26, com gabaritos no banco.</p></div><div><strong>Português + Matemática</strong><p>Preparação alinhada aos conteúdos do edital.</p></div><div><strong>Aprender → praticar → revisar</strong><p>Feedback claro e conquistas por etapas vencidas.</p></div></div><div class="section-head"><h2>Uma preparação que acompanha você.</h2></div><div class="cards"><article class="course-card">${ico('compass')}<h3>Comece pelo diagnóstico</h3><p>O primeiro treino identifica forças e fraquezas. Sua estratégia de estudo será programada de acordo com o que você precisa melhorar, reforçando também seus pontos fortes.</p></article><article class="course-card">${ico('book')}<h3>Aprenda em missões curtas</h3><p>Uma ideia, um exemplo resolvido e uma tentativa sua. Em matemática, novos números e resultados desafiam seu raciocínio a cada treino.</p></article><article class="course-card">${ico('award')}<h3>Celebre o progresso</h3><p>Pontos por prática e conquistas por constância, recuperação de erros e etapas concluídas.</p></article></div><div class="notice spaced">${C.demo?'Versão de demonstração para avaliação. O cadastro real será ativado após configurar o banco independente do curso.':'O cadastro neste preparatório não substitui a inscrição no processo seletivo oficial.'}</div><button class="link" data-action="public-guide">Consultar edital e etapas de ingresso ${ico('arrow')}</button></main><footer>Missão Tiradentes · Preparatório independente para os Colégios Tiradentes da Brigada Militar do RS.<br>Sem vínculo com a instituição. Provas futuras podem mudar; acompanhe o edital oficial.</footer></div>`}
function dashboard(){let ev=evidence(),pr=availablePriorities(),last=state.history.at(-1),tested=course.topics.filter(t=>metrics(t.id).n).length;let totalCorrect=ev.filter(a=>a.correct).length;let saved=activeSaved();const day=new Date().getDate();shell(`${heading(demo?'Olá, estudante 👋':`Olá, ${esc(user.name.split(' ')[0])} 👋`,'Seu próximo passo começa com o que você já sabe.')}<div class="dashboard-grid"><div><section class="hero"><div><div class="eyebrow">${state.history.length?'SUA PRÓXIMA MISSÃO':'VAMOS DESCOBRIR SEU PONTO DE PARTIDA'}</div><h2>${state.history.length?'Uma dúvida a menos.<br>Um passo mais perto.':'Seu caminho começa<br>com um diagnóstico.'}</h2><p>${state.history.length?`Sua trilha prioriza ${esc(pr[0]?.title.toLowerCase()||'as habilidades que faltam avaliar')}. Vamos aprender, praticar e voltar ao que importa.`:'Um treino sem pressão para descobrir suas forças e os conteúdos que merecem atenção.'}</p><button class="btn light" ${state.history.length?`data-lesson="${pr[0]?.id}"`:'data-action="diagnostic"'}>${state.history.length?'Continuar minha trilha':'Fazer meu diagnóstico'} ${ico('arrow')}</button></div><div class="hero-art">${art()}</div></section>${saved?'<div class="notice green spaced">Você tem uma atividade pausada. <button class="link" data-action="resume">Continuar de onde parei →</button></div>':''}<div class="stats"><div class="stat"><span>Último desempenho</span>${ico('chart')}<strong>${last?last.percent+'%':'—'}</strong><small>${last?esc(last.label):'Faça seu primeiro treino'}</small></div><div class="stat"><span>Habilidades avaliadas</span>${ico('compass')}<strong>${tested}<span> / ${course.topics.length}</span></strong><small>Sem estimativas para temas não avaliados</small></div><div class="stat"><span>Missões estudadas</span>${ico('book')}<strong>${state.lessons.length}</strong><small>${xp()} pontos de experiência</small></div></div><div class="section-head"><h2>Sua estratégia de estudo</h2><button class="link" data-page="lessons">Ver minha trilha →</button></div>${strategyHtml(true)}<div class="section-head spaced"><h2>Treinar também faz parte</h2></div><div class="mission"><div class="tile-icon orange">${ico('test')}</div><div class="body"><h3>Simulado 2025/26</h3><p>50 questões no banco · 3 horas · recursos conferidos</p></div><button class="arrow" data-exam="2025-26" aria-label="Iniciar simulado 2025/26">${ico('arrow')}</button></div></div><aside class="dashboard-aside"><div class="panel calendar-panel"><div class="section-head"><h3>Seu ritmo de estudo</h3>${ico('clock')}</div><span class="muted" style="">${new Date().toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</span><div class="calendar">${['D','S','T','Q','Q','S','S'].map(d=>`<span class="day">${d}</span>`).join('')}${Array.from({length:new Date(new Date().getFullYear(),new Date().getMonth(),1).getDay()},()=>'<span></span>').join('')}${Array.from({length:new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()},(_,i)=>`<span class="num ${day===i+1?'today':''}">${i+1}</span>`).join('')}</div><p style="">Uma sessão pequena já conta. Não há punição por fazer uma pausa.</p><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Acertos em questões distintas</h3><div class="progress-ring" style="--p:${ev.length?totalCorrect/ev.length*100:0}%"><div><strong>${ev.length?Math.round(totalCorrect/ev.length*100)+'%':'—'}</strong><small>${ev.length?ev.length+' questões':'Ainda sem diagnóstico'}</small></div></div>${['Português','Matemática'].map(s=>{const a=ev.filter(x=>(topic(x.topic)?.subject||x.subject)===s),pct=a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):0;return `<div class="track"><div class="track-label"><span>${s}</span><b>${a.length?pct+'%':'Não avaliado'}</b></div><div class="bar ${s==='Português'?'purple':''}"><span style="width:${pct}%"></span></div></div>`}).join('')}<span class="muted" style="">Indicador de prática, não previsão de aprovação.</span></div><div class="quote">${ico('spark')}<p>“Ainda não sei” é o começo de “agora entendi”.</p><small>Aprenda. Tente. Celebre. Repita.</small><button class="link" style="display:block;margin-top:20px;" data-page="rewards">Minhas conquistas →</button></div></aside></div>`)}
function lessons(){let filtered=priorities().filter(t=>(subject==='Todos'||t.subject===subject)&&t.title.toLowerCase().includes(query.toLowerCase()));shell(`${heading('Sua trilha de aprendizagem','Conteúdo curto. Exemplos claros. Prática com propósito.')}<div class="notice green">${state.history.length?'A ordem muda conforme suas respostas. Erros e respostas por palpite têm prioridade; temas ainda não avaliados entram antes dos conteúdos com bons resultados.':'Faça o diagnóstico para ordenar a trilha pelo seu desempenho. Você também pode começar por qualquer aula.'} O acervo inicial reúne 25 aulas de fundamentos; alguns tópicos avançados do edital ainda precisam de aprofundamento.</div><input class="search" aria-label="Buscar aula" placeholder="Buscar um conteúdo…" value="${esc(query)}" id="lesson-search"><div class="filters">${['Todos','Português','Matemática'].map(s=>`<button class="filter ${subject===s?'active':''}" data-subject="${s}">${s}</button>`).join('')}</div><div class="cards">${filtered.map(t=>`<article class="course-card"><span class="pill ${t.subject==='Português'?'purple':''}">${t.subject}</span><h3>${esc(t.title)}</h3><p>${esc(t.body.split('. ')[0])}.</p><div class="card-meta">${t.minutes} min · ${esc(status(t.id))}</div><button class="btn outline small" data-lesson="${t.id}">${!canPractice(t.id)?'Revisar conteúdo':state.lessons.includes(t.id)?'Revisar e fazer novo treino':'Estudar agora'} ${ico('arrow')}</button></article>`).join('')||'<div class="empty">Nenhuma aula encontrada. Tente outro termo.</div>'}</div>`)}
function lesson(id){const t=topic(id);if(!t)return;page='lessons';shell(`<div class="lesson"><button class="link" data-page="lessons">← Minha trilha</button><div class="spaced"><span class="pill ${t.subject==='Português'?'purple':''}">${t.subject} · ${t.minutes} min</span><h1 style="margin-top:18px">${esc(t.title)}</h1><p>Uma ideia de cada vez. Primeiro entenda; depois tente sem consultar.</p></div><div class="lesson-block"><div class="eyebrow">01 · ENTENDA A IDEIA</div><p>${esc(t.body)}</p></div><div class="lesson-block"><div class="eyebrow">02 · VEJA UM EXEMPLO</div><div class="example">${esc(t.example)}</div></div><div class="lesson-block"><div class="eyebrow">03 · FAÇA SUA TENTATIVA</div><p style="">Feche a explicação e tente recuperar a ideia. O erro é uma informação sobre o próximo passo.</p>${t.subject==='Matemática'?'<div class="notice green"><strong>Entenda o caminho. Enfrente novos números.</strong><p>Cada treino traz resultados diferentes dos que você já viu nesta habilidade. A explicação aparece depois da sua tentativa.</p></div>':''}${canPractice(t.id)?`<button class="btn" id="practice-start" data-practice="${t.id}">Praticar com novos desafios ${ico('arrow')}</button><p id="practice-msg" role="status"></p>`:`<div class="notice"><p>A explicação continua disponível para revisão. Sua próxima prática será em uma habilidade com novos desafios.</p>${availablePriorities().find(x=>x.id!==id)?`<button class="btn" data-lesson="${availablePriorities().find(x=>x.id!==id).id}">Ir para a próxima prática →</button>`:'<button class="btn outline" data-page="progress">Rever meu histórico →</button>'}</div>`}</div><p style="">${esc(t.trap)} A aula conta como estudada após sua tentativa, e não apenas pela abertura da página.</p></div>`);beginStudy()}
function simulators(){const assessed=assessment();shell(`${heading('Simulados e treinos','Conheça a prova. Descubra suas dúvidas. Aprenda com cada tentativa.')}<section class="hero" style="min-height:190px;grid-template-columns:1fr auto"><div><div class="eyebrow">UM TREINO SEM PRESSÃO</div><h2>${assessed?'Diagnóstico concluído ✓':'Comece pelo diagnóstico'}</h2><p>${assessed?'Sua avaliação já gerou uma estratégia de estudo. Você pode fazer os simulados abaixo; cada resultado atualiza sua trilha.':'O primeiro treino identifica forças e fraquezas. A estratégia de estudo será programada de acordo com sua necessidade de melhorias. Até 12 desafios inéditos, sem pressão de tempo.'}</p>${assessed?'<button class="btn light" data-page="dashboard">Ver minha estratégia →</button><button class="link light-link" data-action="diagnostic">Fazer nova avaliação</button>':'<button class="btn light" data-action="diagnostic">Iniciar diagnóstico →</button>'}</div><div class="hero-art" style="width:180px">${art()}</div></section><div class="section-head spaced"><h2>Provas anteriores, na íntegra</h2><span class="pill">6 edições · 300 questões</span></div><div class="notice green">Os treinos de matemática usam novos números e resultados. Cada prova anterior tem uma tentativa por edição e mantém o caderno original; depois você pode consultar sua correção.</div><div class="cards">${course.exams.map(e=>`<article class="course-card"><span class="pill">Prova ${e.year.replace('-','/')}</span><h3>Simulado de ingresso ${e.year.slice(-2)}</h3><p>25 questões de Português e 25 de Matemática. Responda cada questão diretamente na tela, com os textos e figuras originais.</p><div class="card-meta">50 questões · 3 horas</div><div class="notice" style="margin:0;">${esc(e.status)}</div><button class="btn outline small" data-exam="${e.year}">${completedExam(e.year)?'Ver minha correção':'Começar simulado'} ${ico('arrow')}</button></article>`).join('')}</div>`)}
function completedExam(year){return state.history.find(h=>h.kind==='exam'&&(h.label==='Prova '+year.replace('-','/')||h.items?.some(x=>x.id?.startsWith(year+'-'))))}
function startQuiz(ids,kind='practice',lessonId=null){quiz={ids,index:0,answers:{},confidence:{},kind,lessonId,started:Date.now()};exam=null;results=null;saveActive();renderQuiz(true);beginStudy()}
let generatingPractice=false;
async function freshMath(id,count){if(!demo)return rpc('generate_math',{p_topic:id,p_count:count});const used=new Set([...state.history.flatMap(h=>h.items||[]),...course.questions.filter(q=>q.generated)].map(q=>q.id));const qs=(course.mathVariants||[]).filter(q=>q.topic===id&&!used.has(q.id)).slice(0,count);if(qs.length<count)throw Error('A demonstração tem um conjunto limitado de variações. O curso gera novos desafios no servidor.');return qs.map(q=>({...q,generated:true,source:'Treino com novos números · alinhado ao edital'}))}
async function refreshPractice(){if(demo){const used=new Set([...state.history.flatMap(h=>h.items||[]),...course.questions.filter(q=>q.generated)].map(q=>q.id));practiceAvailability=Object.fromEntries(course.topics.filter(t=>t.subject==='Português').map(t=>[t.id,(course.portugueseVariants||[]).filter(q=>q.topic===t.id&&!used.has(q.id)).length]));return}const rows=await rpc('practice_availability',{});practiceAvailability=Object.fromEntries(rows.map(r=>[r.topic,r.available]));}
async function freshPractice(id,count){if(!demo)return rpc('generate_practice',{p_topic:id,p_count:count});if(topic(id)?.subject==='Matemática')return freshMath(id,count);const used=new Set([...state.history.flatMap(h=>h.items||[]),...course.questions.filter(q=>q.generated)].map(q=>q.id));return (course.portugueseVariants||[]).filter(q=>q.topic===id&&!used.has(q.id)).slice(0,count).map(q=>({...q,generated:true,source:'Novo desafio de Português · alinhado ao edital'}))}
function addPractice(qs){const existing=new Set(course.questions.map(q=>q.id));for(const q of qs)if(!existing.has(q.id)){course.questions.push({...q,generated:true});existing.add(q.id);if(topic(q.topic)?.subject==='Português'&&Object.hasOwn(practiceAvailability,q.topic))practiceAvailability[q.topic]=Math.max(0,practiceAvailability[q.topic]-1)}}
async function startPractice(id){if(generatingPractice)return;if(!canPractice(id)){lesson(id);return}generatingPractice=true;const b=$('#practice-start');if(b){b.disabled=true;b.textContent='Preparando seu novo treino…'}try{const qs=await freshPractice(id,3);if(!qs.length){blockedPractice.add(id);lesson(id);return}addPractice(qs);startQuiz(qs.map(q=>q.id),'practice',id)}catch(err){if(/outro desafio disponível|variações inéditas.*esgotaram/i.test(err.message)){blockedPractice.add(id);await refreshPractice().catch(()=>{});lesson(id)}else{const msg=$('#practice-msg');if(msg)msg.textContent='Não foi possível preparar o treino. '+err.message;else flash(err.message)}}finally{generatingPractice=false;if(b){b.disabled=false;b.textContent='Praticar com novos desafios →'}}}
async function startDiagnostic(){if(generatingPractice)return;generatingPractice=true;const b=$('[data-action="diagnostic"]');if(b){b.disabled=true;b.textContent='Preparando sua avaliação…'}try{const available=availablePriorities(),p=available.filter(t=>t.subject==='Português').slice(0,6),m=available.filter(t=>t.subject==='Matemática').slice(0,6),qs=[];for(const t of [...p,...m])qs.push(...await freshPractice(t.id,1));if(!qs.length)throw Error('Seu histórico já reúne a avaliação disponível. Continue pelas aulas de revisão.');addPractice(qs);startQuiz(qs.map(q=>q.id),'diagnostic')}catch(err){flash(err.message)}finally{generatingPractice=false;if(b){b.disabled=false;b.textContent='Fazer nova avaliação →'}}}

function renderQuiz(reset=false){const q=course.questions.find(q=>q.id===quiz.ids[quiz.index])||(demo?[...(course.mathVariants||[]),...(course.portugueseVariants||[])].find(q=>q.id===quiz.ids[quiz.index]):null);if(!q){flash('Esta questão não está disponível.');quiz=null;render();return}const t=topic(q.topic),n=quiz.ids.length;page='simulators';shell(`<div class="lesson">${heading(quiz.kind==='diagnostic'?'Seu diagnóstico':'Sua tentativa',`${esc(t.title)} · Questão ${quiz.index+1} de ${n}`)}<div class="bar"><span style="width:${(quiz.index+1)/n*100}%"></span></div><div class="question-prompt">${esc(q.prompt)}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${quiz.answers[q.id]===i?'selected':''}" data-answer="${i}" aria-pressed="${quiz.answers[q.id]===i}"><span class="letter">${'ABCDE'[i]}</span>${esc(o)}</button>`).join('')}</div><div class="confidence"><span>Como você chegou à resposta?</span><button class="${quiz.confidence[q.id]==='sure'?'selected':''}" data-confidence="sure">Entendi o caminho</button><button class="${quiz.confidence[q.id]==='guess'?'selected':''}" data-confidence="guess">Fiquei em dúvida</button></div><div class="quiz-footer"><button class="btn outline" data-action="quiz-prev" ${quiz.index===0?'disabled':''}>← Voltar</button><span class="saved">${demo?'Salvo neste navegador':'Atividade salva nesta sessão'}</span><button class="btn" data-action="quiz-next">${quiz.index===n-1?'Ver resultado':'Próxima questão'} ${ico('arrow')}</button></div><button class="link spaced" data-page="simulators">Pausar e continuar depois</button><p style="">${esc(q.source||'Exercício autoral alinhado ao edital')} · A resposta e a explicação aparecem ao concluir.</p></div>`);if(reset)window.scrollTo(0,0)}
async function finishQuiz(){if(!quiz||quiz.submitting)return;const qz=quiz;qz.submitting=true;const next=$('[data-action="quiz-next"]');if(next){next.disabled=true;next.textContent='Salvando sua avaliação…'}let items,serverResult;try{if(demo){items=qz.ids.map(id=>{const q=course.questions.find(x=>x.id===id)||(demo?[...(course.mathVariants||[]),...(course.portugueseVariants||[])].find(x=>x.id===id):null);return {id,topic:q.topic,template:q.template,result_key:q.result_key,selected:qz.answers[id]??null,correct:qz.answers[id]===q.answer,answer:q.answer,explanation:q.explanation,confidence:qz.confidence[id]||'guess',prompt:q.prompt,options:q.options}})}else{const r=await rpc('submit_practice',{p_answers:qz.ids.map(id=>({id,selected:qz.answers[id]??null,confidence:qz.confidence[id]||'guess'})),p_kind:qz.kind,p_lesson:qz.lessonId});items=r.items;serverResult=r;}const correct=items.filter(a=>a.correct).length;const h=serverResult||{id:crypto.randomUUID(),kind:qz.kind,label:qz.kind==='diagnostic'?'Diagnóstico de habilidades':'Prática: '+topic(qz.lessonId||items[0].topic).title,date:new Date().toISOString(),items,percent:Math.round(correct/items.length*100)};state.history.push(h);if(qz.lessonId&&!state.lessons.includes(qz.lessonId))state.lessons.push(qz.lessonId);persist();quiz=null;clearActive();results=h;renderResults();window.scrollTo(0,0);notifyReward();refreshStudy();}catch(e){qz.submitting=false;if(next){next.disabled=false;next.textContent='Ver resultado'}flash(e.message)}}
function notifyReward(){for(const a of achievements())if(a.ok&&!state.rewards.includes(a.id)){state.rewards.push(a.id);flash('Conquista desbloqueada: '+a.title+' ✦')}persist()}
async function examAsset(year){if(demo)return `questoes/${year}.webp`;const r=await api(`/storage/v1/object/sign/questoes/${year}.webp`,{method:'POST',body:JSON.stringify({expiresIn:14400})});return C.supabaseUrl+'/storage/v1'+r.signedURL}
async function startExam(year){const e=course.exams.find(x=>x.year===year);if(!e)return;const done=completedExam(year);if(done){results=done;renderResults();window.scrollTo(0,0);return}modalConfirm('Pronto para o simulado?','Cada edição tem uma tentativa. Você terá 3 horas e pode pausar e retomar antes de finalizar. As questões aparecem diretamente na tela. Respostas em branco contam como erro; a correção segue o gabarito e as ressalvas da edição.',async()=>{try{const rows=demo?course.examQuestions.filter(q=>q.year===year):(await api('/rest/v1/exam_questions_public?select=data&year=eq.'+year+'&order=number.asc')).map(x=>x.data);if(rows.length!==50)throw Error('Esta edição ainda está em preparação.');exam={year,index:1,answers:{},deadline:Date.now()+3*60*60*1000,bank:rows,asset:await examAsset(year),assetCreated:Date.now()};quiz=null;saveActive();renderExam();beginStudy()}catch(err){flash(err.message)}})}
function questionVisual(q,regions,label){return regions.map((r,i)=>`<svg class="question-visual" viewBox="${r.join(' ')}" role="img" aria-label="${esc(label)}${regions.length>1?' · parte '+(i+1):''}" xmlns="http://www.w3.org/2000/svg"><title>${esc(label)}</title><image href="${esc(exam.asset)}" width="${q.atlas_width}" height="${q.atlas_height}"/></svg>`).join('')}
function renderExam(){const e=course.exams.find(x=>x.year===exam.year),q=exam.bank?.find(x=>x.number===exam.index);if(!q){flash('Retome o simulado pela lista de provas para carregar as questões.');exam=null;clearActive();simulators();return}page='simulators';shell(`${heading('Simulado '+e.year.replace('-','/'),'Uma questão por vez, diretamente na tela.')}<div class="notice">${esc(e.status)}. ${e.annulled?.length?'Questões anuladas recebem crédito e ficam fora do diagnóstico.':''}</div><div class="test-layout"><div><div class="page-nav"><button class="btn outline small" data-action="exam-prev" ${exam.index<=1?'disabled':''}>← Anterior</button><span>Questão ${exam.index} de 50</span><button class="btn outline small" data-action="exam-next" ${exam.index>=50?'disabled':''}>Próxima →</button></div><article class="panel question-panel"><span class="pill">${esc(q.subject)} · Questão ${q.number}</span>${q.stimulus.length?`<details class="question-passage" open><summary>Texto de apoio</summary>${questionVisual(q,q.stimulus,'Texto de apoio da questão '+q.number)}</details>`:''}<div class="question-body">${questionVisual(q,q.body,'Enunciado e alternativas da questão '+q.number)}</div><div class="reading-controls"><button class="btn outline" data-action="zoom-question">Ampliar imagem da questão</button><span>Você também pode ler o texto abaixo.</span></div><details class="question-text" open><summary>Texto extraído para apoio à leitura</summary><p>Fórmulas e figuras devem ser conferidas na imagem original acima.</p><pre>${esc(q.original_text)}</pre></details><h3 style="margin-top:24px">Marque sua resposta</h3><div class="exam-options">${[...'ABCDE'].map((a,i)=>`<button class="${exam.answers[exam.index]===a?'selected':''}" data-exam-answer="${a}" aria-pressed="${exam.answers[exam.index]===a}" aria-label="Alternativa ${a}${q.options[i]?': '+esc(q.options[i]):''}">${a}</button>`).join('')}</div><button class="link" data-action="exam-clear">Limpar resposta</button></article></div><aside class="panel"><div class="eyebrow">TEMPO RESTANTE</div><div class="timer" id="timer">03:00:00</div><p style="" id="answered-count">${Object.keys(exam.answers).length} de 50 respondidas</p><h3>Seu cartão de respostas</h3><div class="answer-grid">${Array.from({length:50},(_,i)=>`<button class="${exam.answers[i+1]?'answered':''} ${exam.index===i+1?'current':''}" data-exam-index="${i+1}" aria-label="Questão ${i+1}${exam.answers[i+1]?', respondida '+exam.answers[i+1]:', não respondida'}">${i+1}</button>`).join('')}</div><button class="btn" style="width:100%" data-action="exam-finish">Finalizar simulado</button><button class="link spaced" style="" data-page="simulators">Pausar visualização</button><p style="">O tempo continua durante a pausa para reproduzir a duração da prova.</p></aside></div>`);clearInterval(timer);tick();timer=setInterval(tick,1000)}
function tick(){if(!exam)return;const sec=Math.max(0,Math.ceil((exam.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=[Math.floor(sec/3600),Math.floor(sec%3600/60),sec%60].map(n=>String(n).padStart(2,'0')).join(':');if(!sec){clearInterval(timer);finishExam()}}
async function finishExam(){if(!exam||exam.submitting)return;exam.submitting=true;const e=course.exams.find(x=>x.year===exam.year);try{let items,serverResult;if(demo)items=Array.from({length:50},(_,i)=>{const n=i+1,annulled=e.annulled.includes(n);return {id:e.year+'-'+n,number:n,topic:e.topics[i],subject:n<=25?'Português':'Matemática',selected:exam.answers[n]??null,answer:e.answers[i],correct:annulled||exam.answers[n]===e.answers[i],annulled}});else{serverResult=await rpc('submit_exam',{p_year:exam.year,p_answers:exam.answers});items=serverResult.items}const h=serverResult||{id:crypto.randomUUID(),kind:'exam',label:'Prova '+exam.year.replace('-','/'),date:new Date().toISOString(),items,percent:items.filter(x=>x.correct).length*2};state.history.push(h);persist();clearInterval(timer);exam=null;clearActive();results=h;renderResults();window.scrollTo(0,0);notifyReward();refreshStudy()}catch(e){exam.submitting=false;flash(e.message)}}
function renderResults(){const h=results;if(!h){render();return}const valid=h.items.filter(a=>!a.annulled),isExam=h.kind==='exam';const p=priorities();shell(`${heading('Cada tentativa mostra um caminho.','Confira o resultado e use o feedback no próximo passo.')}<div class="panel results-top"><span class="pill">${esc(h.label)}</span><strong>${h.percent}${isExam?'<span style="font-size:24px"> / 100</span>':'%'}</strong><p>${h.items.filter(x=>x.correct&&!x.annulled).length} acertos em ${valid.length} questões válidas.${isExam&&h.items.some(x=>x.annulled)?' A nota inclui crédito das questões anuladas.':''} ${valid.filter(x=>x.selected===null).length} em branco.</p><button class="btn" data-page="dashboard">Ver minha estratégia de estudo ${ico('arrow')}</button></div><div class="section-head spaced"><h2>Seu próximo passo</h2></div>${strategyHtml()}<div class="panel spaced"><h3>${isExam?'Cartão de correção':'Entenda suas respostas'}</h3>${isExam?`<div class="table-scroll"><table class="table"><thead><tr><th>Questão</th><th>Sua resposta</th><th>Gabarito</th><th>Resultado</th><th>Estudar</th></tr></thead><tbody>${h.items.map(a=>`<tr><td>${a.number}</td><td>${esc(a.selected||'Em branco')}</td><td>${a.annulled?'Anulada':a.answer}</td><td>${a.annulled?'Crédito geral':a.correct?'✓ Acerto':'Revisar'}</td><td>${a.topic&&!a.annulled?`<button class="link" data-lesson="${a.topic}">${esc(topic(a.topic)?.title)} →</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><p style="">As cinco edições mais antigas têm correção por disciplina; a classificação por habilidade está disponível na prova 2025/26. Consulte as ressalvas do gabarito na página de simulados.</p>`:h.items.map((a,i)=>`<div class="lesson-block"><span class="pill ${a.correct?'':'orange'}">${a.correct?'✓ Acerto':'Revisão'} · ${esc(topic(a.topic)?.title)}</span><h3 class="spaced">${i+1}. ${esc(a.prompt)}</h3><p style="">Sua resposta: ${a.selected===null?'Em branco':esc(a.options[a.selected])}<br>Resposta esperada: <b>${esc(a.options[a.answer])}</b></p><div class="example" style="">${esc(a.explanation)}</div><button class="link spaced" data-lesson="${a.topic}">Estudar esta habilidade →</button></div>`).join('')}</div>`)}
function progress(){shell(`${heading('Veja o quanto você avançou.','O diagnóstico fica mais confiável com questões diferentes e novas tentativas.')}<div class="notice green">Acertos e erros são contabilizados por questão distinta, usando a tentativa mais recente. Repetir a mesma questão não aumenta o número de evidências. Pelo menos três questões distintas e 80% de acerto indicam consolidação inicial; isso não certifica domínio do edital.</div><div class="panel"><h3>Mapa de habilidades</h3><div class="table-scroll"><table class="table"><thead><tr><th>Habilidade</th><th>Evidências</th><th>Acertos</th><th>Próximo passo</th></tr></thead><tbody>${course.topics.map(t=>{const m=metrics(t.id);return `<tr><td><button class="link" data-lesson="${t.id}">${esc(t.title)}</button></td><td>${m.n} questões</td><td>${m.rate===null?'—':m.rate+'%'}</td><td>${esc(status(t.id))}</td></tr>`}).join('')}</tbody></table></div><div class="section-head spaced"><h2>Seu histórico</h2></div><div class="panel">${state.history.length?[...state.history].reverse().map(h=>`<div class="history-item"><div><b>${esc(h.label)}</b><p style="margin:5px 0">${new Date(h.date).toLocaleString('pt-BR')} · ${h.items.length} questões</p></div><b>${h.percent}%</b><button class="link" data-result="${h.id}">Rever →</button></div>`).join(''):'<div class="empty">Seu histórico começa com o primeiro diagnóstico.<br><button class="btn spaced" data-action="diagnostic">Começar agora</button></div>'}</div>`)}
function rewards(){const x=xp(),level=Math.floor(x/150)+1;const badges=achievements();shell(`${heading('Seu esforço merece uma conquista.','Pontos por aprender. Marcos por avançar. Sem competição entre alunos.')}<div class="hero" style="min-height:220px"><div><div class="eyebrow">SEU CAMINHO DE CONQUISTAS</div><h2>Nível ${level} · ${['Explorador','Aprendiz','Desbravador','Estrategista'][Math.min(level-1,3)]}</h2><p>${x} XP conquistados. Faltam ${150-x%150} XP para o próximo nível.</p><div class="bar" style="background:#3f6052"><span style="width:${x%150/150*100}%;background:var(--lime)"></span></div></div><div class="hero-art">${art()}</div></div><div class="section-head spaced"><h2>Etapas vencidas</h2><span class="pill">${badges.filter(a=>a.ok).length} de ${badges.length}</span></div><div class="cards">${badges.map(a=>`<article class="course-card" style="${a.ok?'border-color:#7a9869;background:#f0f5e9':''}"><div class="tile-icon ${a.ok?'':'orange'}">${ico(a.icon)}</div><span class="pill ${a.ok?'':'orange'}">${a.ok?'Desbloqueada ✓':'Sua próxima conquista'}</span><h3>${a.title}</h3><p>${a.desc}</p></article>`).join('')}</div><div class="panel spaced"><h3>Como seus pontos funcionam</h3><p>+10 XP pelo primeiro acerto em cada questão distinta; +15 XP por aula estudada e praticada, uma vez; +20 XP por habilidade em que você recuperou um erro; +50 XP por edição de prova inteiramente respondida, uma vez. Os XP conquistados permanecem com você. Novos erros ajudam a ajustar a trilha sem retirar suas conquistas.</p><p>Conquistas são simbólicas nesta versão. Prêmios materiais ou benefícios pagos ainda não foram configurados. Não há ranking público, perda de sequência ou punição por pausas.</p></div>`)}
const source2027='https://www.brigadamilitar.rs.gov.br/upload/arquivos/202608/24130956-edital-202-dec-det-2026-colegio-tiradentes-2027.pdf';
function guideHtml(){return `${heading('O ingresso vai além da prova.','Orientações para o aluno e para quem acompanha sua preparação.')}<div class="notice green">Referência: edital nº 202/DEC-DET/2026, para ingresso em 2027. Conferido em 12/10/2026. Consulte os aditamentos para locais, horários e alterações. <a class="link" href="${source2027}" target="_blank" rel="noopener">Ler edital oficial ↗</a></div><div class="cards"><article class="course-card"><span class="pill">01 · Exame intelectual</span><h3>Português e Matemática</h3><p>50 questões, 25 por disciplina, 2 pontos por questão e duração de 3 horas. Zerar uma disciplina elimina o candidato. Não há redação ou outras disciplinas nesta prova.</p></article><article class="course-card"><span class="pill orange">02 · Exame de saúde</span><h3>Documentação médica</h3><p>Etapa eliminatória. A ficha prevista no edital deve ser preenchida pelos responsáveis e pelo médico, com a declaração de aptidão exigida.</p></article><article class="course-card"><span class="pill purple">03 · Exame físico</span><h3>Apoio, abdominal e corrida</h3><p>Etapa eliminatória com flexão de braços, abdominal e corrida de 12 minutos. O anexo B define execução e índices. A preparação física precisa de acompanhamento profissional adequado.</p></article></div><div class="panel spaced"><h3>Checklist para organizar o ingresso</h3>${['Ler o edital e conferir requisitos de idade e escolaridade','Conferir inscrição e homologação no processo seletivo oficial','Verificar local e horário nos aditamentos da unidade escolhida','Organizar documento de identidade e material permitido','Providenciar ficha médica conforme convocação','Conferir regras e índices do exame físico no anexo B','Conferir documentos e prazos de matrícula','Participar da semana de adaptação prevista após a matrícula'].map((s,i)=>`<label style="display:flex;gap:12px;align-items:flex-start;padding:13px 0;border-bottom:1px solid var(--line);line-height:1.7"><input type="checkbox" data-check="${i}" ${state.checks.includes(i)?'checked':''}>${s}</label>`).join('')}</div><div class="panel spaced"><h3>Fontes e limites do conteúdo</h3><ul class="source-list"><li><a href="https://www.brigadamilitar.rs.gov.br/processo-seletivo-da-rede-dos-colegios-tiradentes-da-brigada-militar-para-o-ano-letivo-de-2027" target="_blank" rel="noopener">Página oficial do ingresso 2027 e aditamentos</a></li><li><a href="https://www.brigadamilitar.rs.gov.br/colegio-tiradentes-2026" target="_blank" rel="noopener">Ingresso 2026: edital, gabarito e recursos</a></li><li><a href="https://www.brigadamilitar.rs.gov.br/colegio-tiradentes-2025" target="_blank" rel="noopener">Ingresso 2025: edital e aditamentos</a></li><li><a href="https://www.brigadamilitar.rs.gov.br/colegios-tiradentes-2024" target="_blank" rel="noopener">Ingresso 2024: edital e aditamentos</a></li><li><a href="https://educationendowmentfoundation.org.uk/news/eef-blog-why-bother-with-retrieval" target="_blank" rel="noopener">EEF: recuperação ativa do conhecimento</a></li><li><a href="https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback" target="_blank" rel="noopener">EEF: feedback para aprendizagem</a></li></ul><p style="">As aulas e os exercícios novos são autorais, alinhados ao edital. São material de estudo, sem previsão garantida de questões futuras. O diagnóstico é uma regra pedagógica transparente e não um teste psicométrico validado.</p><p style="">Acervo inicial fornecido pelo responsável pelo projeto: seis provas e seis gabaritos. As edições 2021/22 e 2022/23 têm gabaritos de fonte secundária. Em 2025/26, as questões 13 e 40 foram anuladas após recursos.</p></div>`}
function guide(){shell(guideHtml())}
async function admin(){page='admin';if(!demo&&user?.role!=='admin'){flash('Apenas o administrador pode acessar esta área.');nav('dashboard');return}let rows;if(demo)rows=[{id:'example',name:'Aluno de exemplo',email:'Dados fictícios',status:adminDemo}];else try{rows=await api('/rest/v1/profiles?select=id,name,email,status,created_at&role=eq.student&order=created_at.desc')}catch(e){flash(e.message);return}shell(`${heading('Acesso com aprovação.','O administrador decide quem pode acessar o curso e os simulados.')} ${demo?'<div class="notice">Ambiente de teste. A solicitação abaixo é fictícia e não cria uma conta real. As decisões valem apenas nesta demonstração.</div>':''}<div class="panel"><h3>Solicitações de cadastro</h3>${rows.length?rows.map(r=>`<div class="admin-row"><b>${esc(r.name)}</b><p style="margin:5px 0">${esc(r.email)} · ${esc({pending:'Aguardando aprovação',approved:'Aprovado',rejected:'Não aprovado',suspended:'Suspenso'}[r.status])}</p><div class="actions">${r.status!=='approved'?`<button class="btn small" data-approve="${r.id}">Aprovar acesso</button>`:''}${r.status==='pending'?`<button class="btn outline small" data-reject="${r.id}">Não aprovar</button>`:''}${r.status==='approved'?`<button class="btn outline small" data-suspend="${r.id}">Suspender</button>`:''}</div></div>`).join(''):'<div class="empty">Nenhuma solicitação recebida.</div>'}</div><div class="panel spaced"><h3>Fluxo de acesso</h3><p>Cadastro → confirmação do e-mail → aguardando aprovação → acesso autorizado. A decisão de aprovação é validada no banco; o aluno não pode alterar seu próprio status ou papel.</p>${demo?'<button class="link" data-action="preview-pending">Ver tela de cadastro pendente →</button>':''}</div>`)}
function render(){if(!demo&&user){if(!study.plans.length&&['pending','approved'].includes(user.status)){onboarding();return}if(user.status!=='approved'){pending();return}}if(!demo&&!user){landing();return}if(quiz){renderQuiz();return}if(exam){renderExam();return}({dashboard,lessons,simulators,routine,progress,rewards,guide,admin}[page]||dashboard)()}
function auth(mode){const ready=!!(C.supabaseUrl&&C.supabaseAnonKey);const html=`<div class="modal-head"><h2>${mode==='signup'?'Seu primeiro passo':mode==='reset'?'Recuperar acesso':'Que bom ter você aqui.'}</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><p>${mode==='signup'?'Crie seu cadastro. Após confirmar o e-mail, aguarde a aprovação do administrador.':mode==='reset'?'Enviaremos um link para você definir uma nova senha.':'Entre para continuar sua preparação.'}</p>${!ready?'<div class="notice">O cadastro real ainda não está ativo. Estamos preparando o banco independente do curso. Você pode explorar a demonstração sem informar dados pessoais.</div>':''}<form class="form" id="auth-form" data-mode="${mode}">${mode==='signup'?'<label for="name">Nome do aluno</label><input id="name" name="name" required maxlength="80" autocomplete="name"><label for="unit">Unidade pretendida</label><select id="unit" name="unit"><option>Pelotas</option><option>Porto Alegre</option><option>Passo Fundo</option><option>Santa Maria</option><option>Ijuí</option><option>Santo Ângelo</option><option>São Gabriel</option><option>Caxias do Sul</option></select>':''}<label for="email">E-mail ${mode==='signup'?'de contato do responsável':''}</label><input id="email" name="email" type="email" required autocomplete="email">${mode!=='reset'?'<label for="password">Senha</label><input id="password" name="password" type="password" required minlength="10" autocomplete="'+(mode==='signup'?'new-password':'current-password')+'">':''}${mode==='signup'?'<label class="check"><input name="consent" type="checkbox" required>Sou responsável pelo aluno ou tenho autorização do responsável para este cadastro e o armazenamento do progresso de estudo.</label>':''}<button class="btn" type="submit" ${ready?'':'disabled'}>${mode==='signup'?'Criar cadastro':mode==='reset'?'Enviar link':'Entrar'}</button><div class="form-msg" role="status" id="auth-msg"></div></form><div style="display:flex;justify-content:space-between;gap:15px;margin-top:18px;"><button class="link" data-auth="${mode==='signup'?'login':'signup'}">${mode==='signup'?'Já tenho cadastro':'Criar cadastro'}</button>${mode==='login'?'<button class="link" data-auth="reset">Esqueci minha senha</button>':''}</div>${C.demo?'<button class="link spaced" data-action="demo">Explorar demonstração →</button>':''}`;openModal(html)}
function openModal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function modalConfirm(title,text,callback){openModal(`<div class="modal-head"><h2>${title}</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><p>${text}</p><div class="quiz-footer"><button class="btn outline" data-action="close-modal">Voltar</button><button class="btn" id="confirm-modal">Continuar ${ico('arrow')}</button></div>`);$('#confirm-modal').onclick=()=>{$('#modal').close();callback()}}
async function api(path,opts={},refresh=true){if(!C.supabaseUrl||!C.supabaseAnonKey)throw Error('O cadastro real ainda não foi ativado.');let r=await fetch(C.supabaseUrl+path,{...opts,headers:{apikey:C.supabaseAnonKey,'Content-Type':'application/json',...(session?.access_token?{Authorization:'Bearer '+session.access_token}:{}),...opts.headers}});if(r.status===401&&session?.refresh_token&&refresh){const s=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})},false);session=s;sessionStorage.setItem('tiradentes-session',JSON.stringify(s));return api(path,opts,false)}const t=await r.text();const data=t?JSON.parse(t):null;if(!r.ok)throw Error(data?.msg||data?.message||data?.error_description||'Não foi possível completar a operação.');return data}
const rpc=(name,body)=>api('/rest/v1/rpc/'+name,{method:'POST',body:JSON.stringify(body)});
async function loadAccount(){const u=await api('/auth/v1/user');const p=await api('/rest/v1/profiles?id=eq.'+u.id+'&select=*');user=p[0];if(user)user.contact_email=u.email;if(!user)throw Error('Não foi possível encontrar o cadastro.');study.plans=await api('/rest/v1/study_commitments?select=*&user_id=eq.'+u.id+'&order=start_day.asc');if(!study.plans.length&&['pending','approved'].includes(user.status)){onboarding();return}if(user.status!=='approved'){pending();return}const [ts,qs,es,hs,ls]=await Promise.all([api('/rest/v1/topics?select=data'),api('/rest/v1/questions_public?select=*'),api('/rest/v1/exams_public?select=*'),api('/rest/v1/attempts?select=data&user_id=eq.'+u.id+'&order=created_at.asc'),api('/rest/v1/lesson_progress?select=topic_id&user_id=eq.'+u.id)]);course={topics:ts.map(x=>x.data),questions:qs,exams:es};course.questions.push(...await rpc('open_practice',{}));state={...emptyState(),history:hs.map(x=>x.data),lessons:ls.map(x=>x.topic_id)};await refreshStudy();await refreshPractice();await loadReportHistory();render()}
function pending(){clearInterval(timer);landing();openModal(`<div class="modal-head"><h2>Cadastro recebido.</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><span class="pill orange">Aguardando aprovação</span><p>Após a confirmação do seu e-mail, o administrador poderá liberar o acesso. Seu compromisso de estudo foi registrado. Enquanto aguarda a aprovação, o curso e os simulados permanecem bloqueados.</p><button class="btn" data-action="recheck">Verificar meu acesso</button>`)}
async function enterDemo(){if(!C.demo)return;$('#modal').close();if(!window.COURSE){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='content.js';s.onload=resolve;s.onerror=reject;document.head.append(s)})}course=window.COURSE;demo=true;sessionStorage.setItem('tiradentes-demo-open','1');state=readStore('tiradentes-demo-v1',emptyState());page='dashboard';await refreshStudy();await refreshPractice();if(!study.plans.length){onboarding();return}render()}
async function authSubmit(e){e.preventDefault();const form=e.target;if(form.id!=='auth-form')return;const f=new FormData(form),mode=form.dataset.mode,btn=form.querySelector('button[type=submit]');btn.disabled=true;$('#auth-msg').textContent='Um instante…';try{if(mode==='signup'){await api('/auth/v1/signup?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),data:{name:f.get('name'),unit:f.get('unit'),guardian_consent:true}})});form.reset();$('#auth-msg').textContent='Cadastro enviado. Confirme seu e-mail e aguarde a aprovação do administrador.'}else if(mode==='reset'){await api('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',body:JSON.stringify({email:f.get('email')})});$('#auth-msg').textContent='Se houver uma conta com este e-mail, você receberá um link de recuperação.'}else{session=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});sessionStorage.setItem('tiradentes-session',JSON.stringify(session));demo=false;$('#modal').close();await loadAccount()}}catch(err){const m=err.message;$('#auth-msg').textContent=/not authorized|email_address_not_authorized/i.test(m)?'O envio de confirmação ainda está em configuração. Tente novamente após a liberação pelo administrador.':/invalid login credentials/i.test(m)?'E-mail ou senha incorretos. Confira os dados e tente novamente.':/email not confirmed/i.test(m)?'Confirme seu e-mail antes de entrar.':/email rate limit|over_email_send_rate_limit/i.test(m)?'O limite temporário de envio foi atingido. Aguarde antes de tentar novamente.':m;$('#auth-msg').classList.add('error')}finally{btn.disabled=false}}
document.addEventListener('submit',e=>{if(e.target.id==='commitment-form')saveCommitment(e);else authSubmit(e)});
document.addEventListener('input',e=>{if(e.target.id==='lesson-search'){query=e.target.value;const pos=e.target.selectionStart;lessons();$('#lesson-search').focus();$('#lesson-search').setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){let n=Number(e.target.dataset.check);state.checks=e.target.checked?[...new Set([...state.checks,n])]:state.checks.filter(x=>x!==n);persist()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;if(!Object.keys(d).length)return;if(b.tagName==='A')e.preventDefault();try{
if(d.report){openSentReports(d.report);return}if(d.page){$('#modal').close();nav(d.page);return}if(d.auth){auth(d.auth);return}if(d.subject){subject=d.subject;lessons();return}if(d.lesson){if(quiz||exam){nav('lessons');return}lesson(d.lesson);return}if(d.practice){await startPractice(d.practice);return}if(d.result){results=state.history.find(h=>h.id===d.result);renderResults();return}if(d.exam){startExam(d.exam);return}
if(d.answer!==undefined&&quiz){quiz.answers[quiz.ids[quiz.index]]=Number(d.answer);saveActive();renderQuiz();return}if(d.confidence&&quiz){quiz.confidence[quiz.ids[quiz.index]]=d.confidence;saveActive();renderQuiz();return}if(d.examAnswer&&exam){exam.answers[exam.index]=d.examAnswer;saveActive();renderExam();return}if(d.examIndex&&exam){exam.index=Number(d.examIndex);const ex=course.exams.find(x=>x.year===exam.year),p=ex.pages.findIndex(ns=>ns.includes(exam.index));if(p>=0)exam.page=p+1;saveActive();renderExam();return}
if(d.approve||d.reject||d.suspend){const id=d.approve||d.reject||d.suspend,status=d.approve?'approved':d.reject?'rejected':'suspended';if(demo)adminDemo=status;else await rpc('set_access',{p_user:id,p_status:status});flash(status==='approved'?'Acesso aprovado.':'Status atualizado.');await admin();return}
switch(d.action){case'zoom-question':$('.question-panel').classList.toggle('zoomed');b.textContent=$('.question-panel').classList.contains('zoomed')?'Reduzir imagem':'Ampliar imagem da questão';break;case'more':openModal(`<div class="modal-head"><h2>Mais do seu curso</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><div class="more-menu">${[['progress','Evolução'],['rewards','Conquistas'],['guide','Guia de ingresso'],...(user?.role==='admin'||demo?[['admin','Administração']]:[])].map(([p,t])=>`<button class="btn outline" data-page="${p}">${t}</button>`).join('')}</div>`);break;case'edit-commitment':onboarding(true);break;case'archive-all':openSentReports();break;case'print-report':flash('O relatório será liberado após o envio semanal.');break;case'enable-guardian-reports':if(!$('#guardian-report-confirm')?.checked){flash('O responsável precisa confirmar a autorização.');break}if(demo){flash('A demonstração não envia e-mails.');break}await rpc('set_guardian_reports',{p_agree:true});await routine();flash('Autorização do responsável registrada.');break;case'stop-guardian-reports':await rpc('set_guardian_reports',{p_agree:false});await routine();flash('Envio semanal desativado.');break;case'download-report':downloadReportPdf();break;case'home':if((demo||user)&&!study.plans.length)onboarding();else if(demo||user)nav('dashboard');else landing();break;case'demo':await enterDemo();break;case'close-modal':$('#modal').close();break;case'logout':saveActive();clearInterval(timer);if(session)await api('/auth/v1/logout',{method:'POST'}).catch(()=>{});quiz=null;exam=null;user=null;demo=false;session=null;course={topics:[],questions:[],exams:[]};state=emptyState();study={plans:[],days:[]};sentReports=[];reportSelection=[];guardianReportConsent=null;practiceAvailability={};blockedPractice=new Set();$('#print-area')?.remove();sessionStorage.removeItem('tiradentes-session');sessionStorage.removeItem('tiradentes-demo-open');landing();break;case'diagnostic':await startDiagnostic();break;case'quiz-prev':quiz.index--;saveActive();renderQuiz(true);break;case'quiz-next':if(quiz.answers[quiz.ids[quiz.index]]===undefined){flash('Escolha uma alternativa antes de continuar.');return}if(quiz.index<quiz.ids.length-1){quiz.index++;saveActive();renderQuiz(true)}else await finishQuiz();break;case'exam-prev':exam.index--;saveActive();renderExam();break;case'exam-next':exam.index++;saveActive();renderExam();break;case'exam-clear':delete exam.answers[exam.index];saveActive();renderExam();break;case'exam-finish':modalConfirm('Finalizar este simulado?',`Você respondeu ${Object.keys(exam.answers).length} de 50 questões. As restantes ficarão em branco.`,finishExam);break;case'resume':{const a=activeSaved();if(a){quiz=a.quiz;exam=a.exam;if(exam){exam.asset=await examAsset(exam.year);exam.assetCreated=Date.now()}render();beginStudy()}break}case'preview-pending':openModal('<div class="modal-head"><h2>Cadastro recebido.</h2><button data-action="close-modal">×</button></div><span class="pill orange">Aguardando aprovação · exemplo</span><p>Seu cadastro foi recebido. Confirme seu e-mail e aguarde a liberação do administrador.</p><p>Curso e simulados bloqueados até a aprovação.</p>');break;case'recheck':$('#modal').close();await loadAccount();break;case'public-guide':openModal('<div class="modal-head"><h2>Guia de ingresso</h2><button data-action="close-modal">×</button></div><p>A prova cobra Português e Matemática. Há também exames de saúde e físico, além da matrícula e adaptação.</p><p><a class="link" href="'+source2027+'" target="_blank" rel="noopener">Ler edital oficial 2027 ↗</a></p>');break;
}}catch(err){flash(err.message)}});
async function boot(){try{const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('access_token')){session={access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token')};sessionStorage.setItem('tiradentes-session',JSON.stringify(session));history.replaceState(null,'',location.pathname);if(hash.get('type')==='recovery'){landing();openModal('<h2>Definir nova senha</h2><form class="form" id="new-password"><label>Nova senha<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><button class="btn">Salvar senha</button></form>');$('#new-password').onsubmit=async e=>{e.preventDefault();try{await api('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:new FormData(e.target).get('password')})});$('#modal').close();await loadAccount()}catch(err){flash(err.message)}};return}}else session=JSON.parse(sessionStorage.getItem('tiradentes-session')||'null');if(session&&C.supabaseUrl){await loadAccount();return}if(C.demo&&sessionStorage.getItem('tiradentes-demo-open')==='1'){await enterDemo();return}landing()}catch(e){user=null;landing();flash(e.message)}}
let study={plans:[],days:[]},studyKey=null,studyKeyDay='',lastEngagement=Date.now(),studyPending=false;
const dayNames=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const localDay=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
const dayDate=s=>new Date(s+'T12:00:00');
const dayISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const shortDate=s=>dayDate(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});
function planAt(day=study.today||localDay()){return study.plans.filter(p=>p.start_day<=day).at(-1)}
function assessment(){return state.history.some(h=>h.kind==='diagnostic'||h.kind==='exam')}
function strategy(){const known=course.topics.filter(t=>metrics(t.id).n);return {weak:known.filter(t=>metrics(t.id).rate<70||metrics(t.id).uncertain).sort((a,b)=>metrics(a.id).rate-metrics(b.id).rate),strong:known.filter(t=>metrics(t.id).rate>=70),review:known.filter(t=>metrics(t.id).correct>0).sort((a,b)=>metrics(b.id).rate-metrics(a.id).rate),unknown:course.topics.filter(t=>!metrics(t.id).n)}}
function upcomingMissions(){const a=strategy(),plan=planAt();if(!plan)return [];for(const key of ['weak','strong','review','unknown'])a[key]=a[key].filter(t=>canPractice(t.id));const good=a.strong[0]||a.review[0];const pool=[{t:a.weak[0],kind:'Melhorar esta habilidade'},{t:good,kind:a.strong.length?'Manter seu ponto forte':'Revisar um acerto'},{t:a.weak[1]||a.unknown[0],kind:a.weak[1]?'Melhorar esta habilidade':'Ampliar o diagnóstico'},{t:a.unknown[0],kind:'Ampliar o diagnóstico'}].filter(x=>x.t);if(!pool.length)pool.push(...availablePriorities().slice(0,3).map(t=>({t,kind:'Revisar esta habilidade'})));const days=[];let date=dayDate(study.today||localDay());for(let i=0;i<28&&days.length<Math.min(plan.days.length,5);i++){const planned=planAt(dayISO(date));if(planned&&planned.days.includes(date.getDay()))days.push({day:dayISO(date),...pool[days.length%pool.length],minutes:planned.minutes});date.setDate(date.getDate()+1)}return days}
function strategyHtml(compact=false){if(!assessment())return '<div class="notice green">Comece pelo diagnóstico. O primeiro treino identifica forças e fraquezas e gera sua estratégia de estudo.<br><button class="btn spaced" data-action="diagnostic">Fazer minha avaliação →</button></div>';const a=strategy(),plan=planAt();const section=(title,list,note)=>`<article class="plan-card"><h3>${title}</h3><p>${note}</p>${list.length?list.slice(0,compact?2:3).map(t=>mission(t,`${metrics(t.id).rate}% · ${metrics(t.id).n} ${metrics(t.id).n===1?'questão':'questões'}`)).join(''):'<p>Ainda precisamos de mais respostas para identificar este grupo.</p>'}</article>`;return `<div class="notice green"><strong>Avaliação concluída. Seu plano está pronto.</strong><p>A cada novo treino, ajustamos os conteúdos. Trabalhe as dúvidas, pratique seus acertos e descubra habilidades ainda não avaliadas. ${plan?`Seu ritmo: ${plan.days.length} dias por semana, ${plan.minutes} minutos por dia.`:'Escolha seu ritmo em Meu compromisso.'}</p><p>Poucas questões mostram um ponto de partida; um acerto isolado ainda precisa de confirmação em novos desafios.</p></div><div class="strategy-grid">${section('Onde melhorar',a.weak,'Entenda a ideia, veja o exemplo e tente novamente.')}${section(a.strong.length?'Seus pontos fortes':'Acertos a consolidar',a.strong.length?a.strong:a.review,a.strong.length?'Retome seus acertos em revisões para manter o conhecimento.':'Há acertos nestas habilidades. Revise o caminho certo para consolidar e avançar em novos desafios.')}</div>${`<div class="panel spaced"><h3>Suas próximas sessões</h3><p>Uma sugestão para os dias que você escolheu. Reserve parte do tempo para entender e o restante para praticar e revisar.</p>${upcomingMissions().map(x=>`<div class="session-card"><span class="pill">${dayNames[dayDate(x.day).getDay()]} · ${shortDate(x.day)}</span><h3>${esc(x.t.title)}</h3><p>${x.kind} · ${x.minutes} min</p><button class="btn outline" data-lesson="${x.t.id}">Começar esta missão →</button></div>`).join('')}<button class="link spaced" data-page="routine">Acompanhar meu compromisso →</button></div>`}`}
function commitmentForm(edit=false){const p=study.plans.at(-1)||{days:[1,3,5],minutes:15,preferred_time:'18:00'};return `<form class="form commitment-form" id="commitment-form"><fieldset><legend>Em quais dias você pretende estudar?</legend><p>Escolha uma rotina que caiba na sua semana. Você pode recuperar uma sessão em outro dia.</p><div class="day-choices">${dayNames.map((name,i)=>`<label><input type="checkbox" name="days" value="${i}" ${p.days.includes(i)?'checked':''}><span>${name}</span></label>`).join('')}</div></fieldset><label for="study-minutes">Tempo de estudo por dia</label><select id="study-minutes" name="minutes">${[10,15,25,40].map(n=>`<option value="${n}" ${p.minutes===n?'selected':''}>${n} minutos${n===15?' · um bom começo':''}</option>`).join('')}</select><label for="study-time">Qual horário funciona melhor para você?</label><input type="time" id="study-time" name="time" value="${p.preferred_time.slice(0,5)}" required><p>Esse horário organiza seu plano. Não enviaremos lembretes automáticos nesta versão.</p><label class="check"><input type="checkbox" required name="agree">Eu escolhi essa rotina e vou procurar cumprir minhas metas. Se precisar, posso ajustar o meu compromisso.</label><div class="form-msg" id="commitment-msg" role="status"></div><button class="btn" type="submit">${edit?'Salvar rotina para a próxima semana':'Assumir meu compromisso →'}</button></form>`}
function onboarding(edit=false){if(edit){openModal(`<div class="modal-head"><h2>Ajustar meu compromisso</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><p>A nova rotina começa na próxima segunda-feira. Seu histórico mantém as metas anteriores.</p>${commitmentForm(true)}`);return}clearInterval(timer);$('#app').innerHTML=`<div class="onboarding"><header>${brand()}<button class="btn outline" data-action="logout">Sair</button></header><main id="main"><span class="pill">Seu primeiro compromisso</span><h1>Um pouco por dia.<br>Um plano que cabe na sua vida.</h1><p>Antes de começar, vamos combinar seu ritmo. Seu compromisso ajuda a organizar a estratégia de estudo e acompanhar sua constância.</p><div class="notice green">Toda semana você verá seu feedback. Após o envio ao responsável, o relatório ficará no histórico para baixar e compartilhar com a escola.</div><div class="panel">${commitmentForm()}</div><p>A liberação do curso também depende da aprovação do administrador.</p></main></div>`}
async function saveCommitment(e){e.preventDefault();const f=new FormData(e.target),days=f.getAll('days').map(Number),btn=e.target.querySelector('[type=submit]'),msg=$('#commitment-msg');if(!days.length){msg.textContent='Escolha pelo menos um dia para estudar.';return}btn.disabled=true;try{const value=demo?{days,minutes:Number(f.get('minutes')),preferred_time:f.get('time'),start_day:localDay()}:await rpc('save_commitment',{p_days:days,p_minutes:Number(f.get('minutes')),p_time:f.get('time')});if(demo){study.plans.push(value);localStorage.setItem('tiradentes-demo-plan',JSON.stringify(study.plans))}$('#modal').close();if(demo)render();else await loadAccount();flash('Compromisso registrado. Vamos dar o próximo passo.')}catch(err){msg.textContent=err.message;btn.disabled=false}}
async function refreshStudy(){if(demo){study.plans=readStore('tiradentes-demo-plan',study.plans);study.days=[...new Set(state.history.map(h=>h.date.slice(0,10)))].map(day=>({day,answers:state.history.filter(h=>h.date.slice(0,10)===day).reduce((n,h)=>n+h.items.filter(a=>a.selected!==null&&!a.annulled).length,0),seconds:0}));study.today=localDay();return}if(user?.status==='approved')study=await rpc('study_overview',{});}
function periodSummary(start,end){const now=study.today||localDay();let scheduled=0,minutesGoal=0;const dates=[];for(let d=dayDate(start);dayISO(d)<=end;d.setDate(d.getDate()+1)){const day=dayISO(d),p=planAt(day);if(p&&p.days.includes(d.getDay())){scheduled++;minutesGoal+=p.minutes;dates.push(day)}}const observed=study.days.filter(d=>d.day>=start&&d.day<=end&&d.day<=now);const practiced=observed.filter(d=>d.answers>0).length,seconds=observed.reduce((n,d)=>n+Number(d.seconds),0);const closed=end<now;return {start,end,scheduled,minutesGoal,practiced,minutes:Math.floor(seconds/60),closed,percent:scheduled?Math.min(100,Math.round(practiced/scheduled*100)):null,elapsed:dates.filter(d=>d<=now).length}}
function periods(mode='week'){const first=study.plans[0]?.start_day;if(!first)return [];const now=study.today||localDay(),out=[];let d=dayDate(first);if(mode==='week')d.setDate(d.getDate()-((d.getDay()+6)%7));else d.setDate(1);for(let i=0;i<520&&dayISO(d)<=now;i++){let end=new Date(d);if(mode==='week')end.setDate(end.getDate()+6);else{end.setMonth(end.getMonth()+1);end.setDate(0)}out.push(periodSummary(dayISO(d),dayISO(end)));if(mode==='week')d.setDate(d.getDate()+7);else d.setMonth(d.getMonth()+1)}return out}
function feedback(p){if(!p.scheduled)return 'Período sem meta de estudo.';if(!p.closed)return p.practiced>=p.scheduled?'Você já cumpriu sua meta de dias deste período. Continue no seu ritmo.':`O período está em andamento. Você praticou em ${p.practiced} dia${p.practiced===1?'':'s'}; sua meta é ${p.scheduled}. Planeje o próximo encontro com o curso.`;if(p.practiced>=p.scheduled)return 'Meta de frequência cumprida. Sua constância cria oportunidades de aprender e revisar.';if(p.practiced)return `Você cumpriu parte da meta. Para o próximo período, escolha sessões curtas e um horário viável. Ajuste a rotina se necessário.`;return 'Não houve prática concluída neste período. Retome com uma sessão pequena e uma meta que caiba na sua rotina.'}
function reportCard(p){return `<article class="panel report-card"><div class="section-head"><h3>${shortDate(p.start)} a ${shortDate(p.end)}</h3><span class="pill ${p.closed?'':'orange'}">${p.closed?'Período concluído':'Em andamento'}</span></div><div class="report-stats"><div><strong>${p.practiced} / ${p.scheduled}</strong><span>Dias de prática / meta</span></div><div><strong>${p.minutes} / ${p.minutesGoal} min</strong><span>Tempo ativo registrado / meta</span></div></div><p>${feedback(p)}</p>${p.closed&&p.scheduled?`<p>Frequência cumprida: <strong>${p.percent}%</strong>. Tempo registrado: <strong>${Math.min(100,Math.round(p.minutes/p.minutesGoal*100))}%</strong> da meta.</p>`:'<p>O fechamento considera o período completo. As metas futuras ainda não representam faltas.</p>'}</article>`}
async function routine(){try{await refreshStudy();await loadReportHistory()}catch(err){flash(err.message);return}const plan=planAt(),future=study.plans.find(p=>p.start_day>(study.today||localDay()));shell(`${heading('Meu compromisso de estudo','Seu ritmo, suas metas e o feedback de cada período.')}<div class="hero routine-hero"><div><div class="eyebrow">PEQUENOS PASSOS QUE SE REPETEM</div><h2>${plan?`${plan.days.length} dias por semana.<br>${plan.minutes} minutos por dia.`:'Vamos escolher sua rotina?'}</h2><p>${plan?`${plan.days.map(d=>dayNames[d]).join(', ')} · horário escolhido: ${plan.preferred_time.slice(0,5)}. Desde ${shortDate(plan.start_day)}.`:'Escolha um compromisso para organizar seu estudo.'}</p><button class="btn light" data-action="edit-commitment">${plan?'Ajustar meu compromisso':'Escolher minha rotina'}</button></div></div>${future?`<div class="notice green spaced">Nova rotina registrada para ${shortDate(future.start_day)}: ${future.days.length} dias por semana, ${future.minutes} minutos por dia.</div>`:''}<div class="section-head spaced"><h2>Feedback semanal</h2></div>${[...periods()].reverse().slice(0,8).map(reportCard).join('')||'<div class="empty">Seu acompanhamento começa ao registrar o compromisso.</div>'}<div class="section-head spaced"><h2>Visão mensal</h2></div>${[...periods('month')].reverse().slice(0,3).map(reportCard).join('')}${guardianReportsHtml()}${reportArchiveHtml()}<div class="panel spaced"><h3>Como seu compromisso é acompanhado</h3><p>Um dia de prática é registrado ao concluir uma atividade com pelo menos uma resposta válida. O tempo conta nas aulas e atividades enquanto a página está visível e em uso. Dias e minutos são apresentados separadamente.</p><p>O histórico descreve atividade no curso. Não é avaliação oficial da escola ou certificação de conduta fora da plataforma.</p></div>`)}
// Small, dependency-free PDF export using standard Helvetica and WinAnsi text.
function buildReportPdf(lines){const cp={'€':128,'“':147,'”':148,'‘':145,'’':146,'–':150,'—':151,'…':133};const encode=t=>Array.from(String(t)).map(c=>c.charCodeAt(0)<=255?c:String.fromCharCode(cp[c]||63)).join('');const literal=t=>encode(t).replace(/[\\()]/g,c=>'\\'+c).replace(/[\r\n]/g,' ');const objects=[null,'<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];const pages=[];let stream='',y=788;const finish=()=>{const pageId=objects.length,contentId=pageId+1;stream+=`BT /F1 10 Tf 1 0 0 1 50 30 Tm (Missao Tiradentes - ${pages.length+1}) Tj ET\n`;objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`,`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);pages.push(pageId);stream='';y=788};for(const line of lines){const size=line.size||12,limit=Math.max(30,Math.floor(485/(size*.59)));const words=String(line.text).split(/\s+/);let row='';const rows=[];for(const word of words){if(row.length+word.length+1>limit&&row){rows.push(row);row=''}if(word.length>limit){if(row){rows.push(row);row=''}for(let i=0;i<word.length;i+=limit)rows.push(word.slice(i,i+limit));continue}row+=(row?' ':'')+word}rows.push(row);for(const text of rows){if(y<size*1.5+55)finish();stream+=`BT /${line.size?'F2':'F1'} ${size} Tf 1 0 0 1 50 ${y} Tm (${literal(text)}) Tj ET\n`;y-=size*1.6}if(line.size)y-=6}if(stream||!pages.length)finish();objects[2]=`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map(id=>id+' 0 R').join(' ')}] >>`;let pdf='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets.push(pdf.length);pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`}const xref=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`+offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Uint8Array(Array.from(pdf,c=>c.charCodeAt(0)))}
function downloadReportPdf(){if(!reportSelection.length||reportSelection.some(r=>r.status!=='sent'||!r.sent_at)){flash('Aguarde o envio semanal confirmado.');return}const bytes=buildReportPdf(reportLines()),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download='historico-missao-tiradentes.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);flash('Relatório em PDF preparado para download.')}

let sentReports=[],guardianReportConsent=null,reportSelection=[];
async function loadReportHistory(){if(demo){sentReports=[];guardianReportConsent=null;return}const [reports,consents]=await Promise.all([api('/rest/v1/weekly_reports?select=id,week_start,week_end,data,status,sent_at&user_id=eq.'+user.id+'&order=week_start.desc'),api('/rest/v1/guardian_report_consents?select=*&user_id=eq.'+user.id)]);sentReports=reports;guardianReportConsent=consents[0]||null;}
function guardianReportsHtml(){const address=guardianReportConsent?.email||user?.contact_email||user?.email||'e-mail do cadastro';return `<div class="panel spaced"><h3>Relatório semanal para o responsável</h3><p>O fechamento considera segunda a domingo. O envio está programado para segunda-feira, às 8h, no horário de Brasília, após ativar o serviço de e-mail.</p>${guardianReportConsent?.active?`<div class="notice green">Autorização registrada para <strong>${esc(address)}</strong>.</div><button class="btn outline" data-action="stop-guardian-reports">Desativar envio semanal</button>`:`<p>Destino: <strong>${esc(address)}</strong>. O e-mail precisa estar confirmado no cadastro.</p><label class="guardian-check"><input id="guardian-report-confirm" type="checkbox">Sou o responsável por este aluno e autorizo receber neste e-mail seu nome, cumprimento das metas, tempo de estudo e resultados das atividades, uma vez por semana.</label><button class="btn spaced" data-action="enable-guardian-reports">Autorizar meus relatórios semanais</button>`}<p>Somente relatórios com envio confirmado ficam disponíveis para download. Falhas de envio não liberam o arquivo.</p></div>`}
function reportArchiveHtml(){return `<div class="section-head spaced"><h2>Histórico de relatórios enviados</h2></div>${sentReports.length?`<div class="panel">${sentReports.map(r=>`<div class="history-item"><div><h3>${shortDate(r.week_start)} a ${shortDate(r.week_end)}</h3><p>Enviado em ${new Date(r.sent_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}.</p><p>${r.data.practiced} / ${r.data.scheduled} dias de prática · ${r.data.minutes} / ${r.data.minutesGoal} min.</p></div><button class="btn outline" data-report="${r.id}">Ver e baixar este relatório</button></div>`).join('')}</div><button class="btn spaced" data-action="archive-all">Baixar histórico dos relatórios enviados</button>`:'<div class="empty">Seu histórico será liberado após o primeiro envio semanal confirmado. A semana em andamento pode ser acompanhada acima, sem download.</div>'}<p>O histórico preserva o relatório fechado e as metas daquele período, mesmo após ajustes na rotina. O download reúne apenas semanas que já foram enviadas ao responsável.</p>`}
function reportLines(){const reports=[...reportSelection].sort((a,b)=>a.week_start.localeCompare(b.week_start));if(!reports.length)return [];const first=reports[0].data;const lines=[{text:'MISSÃO TIRADENTES',size:12},{text:'Histórico de relatórios semanais',size:20},{text:'Aluno: '+first.student_name},{text:'Unidade pretendida: '+(first.unit||'Não informada')},{text:'Arquivo preparado em: '+shortDate(localDay())},{text:''}];for(const r of reports){const d=r.data;lines.push({text:`${shortDate(r.week_start)} a ${shortDate(r.week_end)}`,size:17},{text:'Envio confirmado em: '+new Date(r.sent_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})},{text:`Dias de prática: ${d.practiced} / ${d.scheduled}. Tempo ativo registrado: ${d.minutes} / ${d.minutesGoal} minutos.`},{text:feedback(d)});const active=d.plans?.filter(p=>p.start_day<=r.week_end).at(-1);if(active)lines.push({text:`Rotina: ${active.days.map(i=>dayNames[i]).join(', ')}. ${active.minutes} minutos por dia, às ${active.preferred_time.slice(0,5)}.`});for(const h of d.history||[])lines.push({text:`${h.label}: ${h.percent}%, ${h.items.length} questões.`});if(!d.history?.length)lines.push({text:'Nenhuma atividade concluída nesta semana.'});lines.push({text:''})}lines.push({text:'Sobre este histórico',size:17},{text:'Este documento reúne somente relatórios semanais com envio confirmado ao responsável. Apresenta metas declaradas, atividades concluídas e tempo ativo registrado no curso. Atividades fora da plataforma não são medidas.'},{text:'Preparatório independente Missão Tiradentes, sem vínculo institucional com a escola. O histórico não é uma avaliação oficial da escola, certificado de conduta fora da plataforma ou garantia de ingresso. Compartilhamento por decisão do aluno e responsável.'});return lines}
function openSentReports(id=null){reportSelection=id?sentReports.filter(r=>r.id===id):[...sentReports];if(!reportSelection.length||reportSelection.some(r=>r.status!=='sent'||!r.sent_at)){flash('O download fica disponível após o envio semanal confirmado.');return}const first=reportSelection[0].data,html=`<div class="report-document"><h1>Histórico semanal enviado</h1><p>Aluno: <strong>${esc(first.student_name)}</strong></p>${[...reportSelection].reverse().map(r=>`<p>Enviado em ${new Date(r.sent_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</p>${reportCard(r.data)}<div class="panel"><h3>Atividades do período</h3>${(r.data.history||[]).map(h=>`<p>${esc(h.label)} · ${h.percent}% · ${h.items.length} questões.</p>`).join('')||'<p>Nenhuma atividade concluída.</p>'}</div>`).join('')}</div>`;let area=$('#print-area');if(!area){area=document.createElement('section');area.id='print-area';document.body.append(area)}area.innerHTML=html;openModal(`<div class="modal-head"><h2>Relatório já enviado</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><p>Este documento contém somente períodos com envio confirmado ao responsável.</p><button class="btn" data-action="download-report">Baixar relatório em PDF</button>${html}`)}

for(const event of ['pointerdown','keydown','scroll','touchstart'])document.addEventListener(event,()=>lastEngagement=Date.now(),{passive:true});
function beginStudy(){studyKey=crypto.randomUUID();studyKeyDay=localDay();lastEngagement=Date.now();trackStudy()}
async function trackStudy(){const active=(quiz||exam||page==='lessons'&&!!$('.lesson-block'));if(demo||!user||user.status!=='approved'||!active||document.visibilityState!=='visible'||Date.now()-lastEngagement>180000||studyPending)return;const day=localDay();if(studyKeyDay!==day){studyKey=crypto.randomUUID();studyKeyDay=day}studyPending=true;try{await rpc('study_tick',{p_key:studyKey})}catch(err){console.warn('Não foi possível registrar o tempo de estudo.')}finally{studyPending=false}}
setInterval(trackStudy,30000);

boot();
